property.value:
/**
 * Renames the element according to the naming convention selected for it in
 * Service Settings. "manual" (or an unset field) leaves the name untouched.
 *
 * namingConventionField: the field's title in Service Settings, e.g. "Operation Naming Convention".
 */
function applyNamingConvention(element, namingConventionField) {
    const serviceSettingsId = "370723b8-0896-465f-acc7-099d8f36e052";
    const namingConvention = application.getSettings(serviceSettingsId)?.getField(namingConventionField)?.value;

    switch (namingConvention) {
        case "pascal-case":
            element.setName(toPascalCase(element.getName()));
            break;
        case "camel-case":
            element.setName(toCamelCase(element.getName()));
            break;
    }
}
